questionvariables.text:
sind(t) := sin(%pi*t/180);
cosd(t) := cos(%pi*t/180);
deg(ex) := subst([sin=sind, cos=cosd], ex);
badkind(ex) := listp(ex) or setp(ex) or (not atom(ex) and member(op(ex), [">", "<", ">=", "<=", "#", "and", "or", "not", "nounand", "nounor", "nounnot"]));
validate_wave(ex) := block([cy], if badkind(ex) or not every(lambda([v], member(v, [x, y])), listofvars(ex)) or freeof(x, ex) then return("Type one equation of the form y = ..., such as y=2*sin(3*x), with x for the angle in degrees."), if not atom(ex) and op(ex) = "=" then (cy: ev(ratsimp(diff(lhs(ex)-rhs(ex), y)), simp), if freeof(x, cy) and freeof(y, cy) and is(cy # 0) then "" else "Type one equation of the form y = ..., such as y=2*sin(3*x), with x for the angle in degrees.") elseif freeof(y, ex) then "" else "Type one equation of the form y = ..., such as y=2*sin(3*x), with x for the angle in degrees.");
/* Design: equation of a transformed sine graph with two stretches; any equivalent equation is accepted. x and y are formal symbols only. Source: adapted from SMP AS/A2 Core 2, Chapter 7, Exercise B, Q1. */
L: [[1,3,2],[0,2,3],[1,2,1/2],[0,4,2],[1,5/2,3],[0,3,1/2],[1,4,4],[0,3/2,4],[1,2,3/2],[0,5,2/3]];
ix: 1+rand(10);
fs: L[ix][1]; a: L[ix][2]; b: L[ix][3];
per: 360/b; xmax: max(360, per);
F(t) := if fs = 1 then sin(t) else cos(t);
G(t) := if fs = 1 then cos(t) else sin(t);
ta: a*F(b*x);
talt: if fs = 1 then a*cos(b*x-90) else a*sin(b*x+90);
drec: a*F(x/b); ddbl: 2*a*F(b*x); doth: a*G(b*x);
tans1: y = ta; tans2: y = talt; tdrec: y = drec; tddbl: y = ddbl; tdoth: y = doth; tplus: y = ta+1;
samp: [10, 37, 55, 100, 140, 200, 263, 333];
tv: map(lambda([v], float(ev(deg(ta), x=v))), samp);
vrec: map(lambda([v], float(ev(deg(drec), x=v))), samp);
vdbl: map(lambda([v], float(ev(deg(ddbl), x=v))), samp);
voth: map(lambda([v], float(ev(deg(doth), x=v))), samp);
y0: if fs = 1 then 0 else a;
xfirst: if fs = 1 then per/4 else per;
fword: if fs = 1 then "sine (it starts at 0)" else "cosine (it starts at a maximum)";
ylo: -a-1; yhi: a+1;
/* When the period is short, label every half period (labels at 22.5 degree steps overlap when b = 4). */
xt: if per < 120 then per/2 else per/4; xg: per/12;
nice(v) := block([r], r: floor(1000*v+1/2)/1000, if integerp(r) then r else float(r));
trev: ta = y;
xq: per/4; gq: if fs = 1 then a else 0;

feedbackvariables.text:
e0: if not atom(ans1) and op(ans1) = "=" then lhs(ans1)-rhs(ans1) else false;
e1: if e0 = false then ans1 else -subst(y=0, e0)/ratsimp(diff(e0, y));
lv: map(lambda([v], float(ev(deg(e1), x=v))), samp);
nearv(u) := is(lmax(abs(lv - u)) < 0.001);
own0: float(ev(deg(e1), x=0)); ownq: float(ev(deg(e1), x=xq));
ownok: numberp(own0) and numberp(ownq);
